	image = "shertul_fortress_lore2.png",
	lore = function() return _t[[In this picture a huge god with glowing eyes towers above the land, and in his right hand he holds high the sun. The other gods are running from him, wincing from the light.
There is some text underneath ]]..(not game.player:attr("speaks_shertul") and _t[[which you do not understand: #{italic}#'Fa AMAKTHEL tabak, ik koru bazan tro yu, ik ranaheli tobol don schek ruun. Ik blana dem Soli as banafel ik goriz uf Eyal ik blod, "Tro fasa goru domus asam, ik goru domit tro Eyal."'#{normal}#]] or _t[[#{italic}#'But AMAKTHEL came, and his might surpassed all else, and the petty gods fled before his glory. And he made the Sun from his breath and held it above the world and said, "All that this light touches shall be mine, and this light shall touch all the world.'#{normal}#]])
	end,
}

newLore{
	id = "shertul-fortress-3",
	category = "sher'tul",
	name = _t"third mural painting", always_pop = true,
	image = "shertul_fortress_lore3.png",
	lore = function() return _t[[This picture shows the huge god holding some smaller figures in his hands and pointing out at the lands beyond. You imagine these figures must be the Sher'Tul.
There is some text beneath ]]..(not game.player:attr("speaks_shertul") and _t[[[[SOURCE_MATCH_1]]]] or _t[[#{italic}#'And AMAKTHEL made the SHER'TUL, and gave unto us the powers to achieve all that we set our will to, and said to us "Go forth to where the light touches and take all for your own."'#{normal}#]])
	end,
}

newLore{
	id = "shertul-fortress-4",
	category = "sher'tul",
	name = _t"fourth mural painting", always_pop = true,
	image = "shertul_fortress_lore4.png",
	lore = function() return _t[[You see a mural showing a huge metropolis made of crystal, with small islands of stone floating in the air behind it. In the foreground is sitting a Sher'Tul, with a hand stretched up to the sky.
There is some text beneath ]]..(not game.player:attr("speaks_shertul") and _t[[which you do not understand: #{italic}#'Batialatoth ro Eyal, ik rinsi akan fronseth sumit kurameth ik linnet pora gasios aeren. Ach nen beswar goreg.'#{normal}#]] or _t[[#{italic}#'We conquered the world, and built for ourselves towering cities of crystal and fortresses that travelled the skies. But some were not content...'#{normal}#]])
	end,
}

